/// <summary>
/// Extension class for AVARUMUnitOfMeasureEventHandleCls
/// </summary>
[ExtensionOf(classStr(UnitOfMeasureEventHandler))]
final class AVARUMUnitOfMeasureEventHandleCls_Extension
{
}

Method.Source:
/// <summary>
/// Handles the event when a new UnitOfMeasureLookup form is created from a lookup form.
/// </summary>
/// <param name = "_formRun">The form run instance.</param>
/// <param name = "_result">The result of the event handler.</param>
static void newUnitOfMeasureLookupFromLookupForm(FormRun _formRun, EventHandlerResult _result)
{
    next newUnitOfMeasureLookupFromLookupForm(_formRun, _result);

    var unitOfMeasureLookup = _result.result() as UnitOfMeasureLookup;

    if (_formRun.args().dataset())
    {
        switch (_formRun.args().dataset())
        {
            case tablenum(InventTableModule):
                InventTableModule inventTableModule = _formRun.args().record() as InventTableModule;

                switch (inventTableModule.ModuleType)
                {
                    case ModuleInventPurchSales::AVARUMSalesForProductVariants:    
                        EcoResProduct product;

                        product = EcoResProduct::findByDisplayProductNumber(inventTableModule.ItemId);
                        unitOfMeasureLookup.parmShowConvertibleUnitsTab(true);
                        unitOfMeasureLookup.parmProduct(product.RecId);
                        _result.result(unitOfMeasureLookup);
                        return;
                }
        }
    }
}
